/**
 * Same-origin invoice PDF gateway with private R2 caching.
 *
 * `POST /api/invoice-generation/logs/{logId}/pdf` authenticates the browser
 * request, verifies the Ledger log scope, computes the shared PDF fingerprint
 * from the invoice snapshot, and serves the matching R2 object when one is
 * stored. Otherwise it calls the original stateless renderer, saves the
 * validated PDF with a conditional write (so a concurrent generation or a
 * deletion marker can win), and returns the generated bytes either way.
 * `?force=1` skips the R2 hit and always renders, replacing any matching
 * stored object with the fresh bytes.
 *
 * `DELETE /api/invoice-generation/logs/{logId}/invoices/{invoiceId}` replaces
 * the stored object with a small deletion marker so renders that read the
 * pre-deletion object can no longer restore its bytes.
 *
 * The older unscoped `/pdf` and `/isdoc` renderer routes remain uncached in
 * `worker/invoice-renderer.ts`; the external renderer contract is unchanged.
 */

import {
    authorizeStorRequest,
    LedgerAdminAuthorizationError,
    LedgerAdminConfigurationError,
    type LedgerAdminIdentity,
} from "@hearthlog/sdk/server";
import { LedgerScopeError, verifyLogAppId } from "@hearthlog/sdk/server";
import {
    computeInvoicePdfFingerprint,
    INVOICE_PDF_RENDERER_REVISION,
} from "../api/invoice-pdf-fingerprint.js";

const INVOICE_RENDERER_PREFIX = "/api/invoice-generation";
const RENDER_PATH = "/api/invoice-generation/pdf";
const UUID = "[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}";
const INVOICE_ID = "[0-9a-zA-Z][0-9a-zA-Z_-]{0,63}";
const PDF_ROUTE = new RegExp(
    `^${INVOICE_RENDERER_PREFIX}/logs/(${UUID})/pdf$`,
);
const INVOICE_ROUTE = new RegExp(
    `^${INVOICE_RENDERER_PREFIX}/logs/(${UUID})/invoices/(${INVOICE_ID})$`,
);
/** The renderer accepts a single invoice snapshot; never buffer more than this. */
const MAX_REQUEST_BYTES = 1024 * 1024;
const PDF_MAGIC = "%PDF-";

export type InvoicePdfCacheEnv = Pick<
    Env,
    | "CF_ACCESS_APP_AUD"
    | "CF_ACCESS_TEAM_DOMAIN"
    | "LEDGER"
    | "LEDGER_AUTH_TOKEN"
    | "STOR_AUTHORIZED_EMAILS"
    | "INVOICE_RENDERER_TOKEN"
    | "INVOICE_RENDERER_ORIGIN"
    | "INVOICE_PDFS"
>;

type StorAuthorizer = (
    request: Request,
    env: InvoicePdfCacheEnv,
) => Promise<LedgerAdminIdentity>;

export async function handleInvoicePdfRequest(
    request: Request,
    env: InvoicePdfCacheEnv,
    authorize: StorAuthorizer = authorizeStorRequest,
): Promise<Response> {
    const url = new URL(request.url);
    const pdfRoute = url.pathname.match(PDF_ROUTE);
    const invoiceRoute = url.pathname.match(INVOICE_ROUTE);
    if (
        (!pdfRoute && !invoiceRoute) ||
        (pdfRoute && request.method !== "POST") ||
        (invoiceRoute && request.method !== "DELETE")
    ) {
        return pdfError(
            404,
            "invoice_pdf_route_not_found",
            "Invoice PDF route not found",
        );
    }
    if (!env.LEDGER_AUTH_TOKEN || !env.INVOICE_RENDERER_TOKEN || !env.INVOICE_RENDERER_ORIGIN || !env.INVOICE_PDFS) {
        return pdfError(
            503,
            "invoice_pdf_cache_unconfigured",
            "Invoice PDF caching is not configured",
        );
    }
    const origin = request.headers.get("Origin");
    if (origin !== null && origin !== url.origin) {
        return pdfError(
            403,
            "origin_not_allowed",
            "Cross-origin invoice PDF requests are not allowed",
        );
    }

    try {
        await authorize(request, env);
    } catch (error) {
        if (error instanceof LedgerAdminConfigurationError) {
            return pdfError(
                503,
                "invoice_pdf_cache_unconfigured",
                "Invoice PDF caching is not configured",
            );
        }
        if (error instanceof LedgerAdminAuthorizationError) {
            return pdfError(403, "invoice_pdf_forbidden", "Hearthlog access is required");
        }
        return pdfError(403, "invoice_pdf_forbidden", "Hearthlog access is required");
    }

    const logId = (pdfRoute ?? invoiceRoute)![1]!;
    let appId: string;
    try {
        appId = await verifyLogAppId(logId, env);
    } catch (error) {
        if (error instanceof LedgerScopeError) {
            return pdfError(error.status, error.code, error.message);
        }
        return pdfError(
            503,
            "ledger_verification_failed",
            "The selected log could not be verified",
        );
    }

    const key = invoiceRoute
        ? `v1/${appId}/${logId}/invoices/${invoiceRoute[2]!}`
        : "";
    if (invoiceRoute) {
        return deleteInvoicePdf(env.INVOICE_PDFS, key, logId, invoiceRoute[2]!);
    }
    return generateOrServeInvoicePdf(
        request,
        env,
        appId,
        logId,
        url.searchParams.get("force") === "1",
    );
}

async function generateOrServeInvoicePdf(
    request: Request,
    env: InvoicePdfCacheEnv,
    appId: string,
    logId: string,
    forceRegenerate: boolean,
): Promise<Response> {
    if (!isJsonContentType(request.headers.get("Content-Type"))) {
        return pdfError(
            415,
            "unsupported_media_type",
            "Invoice renderer requests must be application/json",
        );
    }
    const declaredLength = Number(request.headers.get("Content-Length"));
    if (Number.isFinite(declaredLength) && declaredLength > MAX_REQUEST_BYTES) {
        return tooLargeError();
    }

    let body: ArrayBuffer;
    try {
        body = await request.arrayBuffer();
    } catch {
        return pdfError(
            400,
            "invoice_snapshot_unreadable",
            "The invoice snapshot could not be read",
        );
    }
    if (body.byteLength > MAX_REQUEST_BYTES) return tooLargeError();

    let snapshot: unknown;
    try {
        snapshot = JSON.parse(new TextDecoder().decode(body));
    } catch {
        return pdfError(
            400,
            "invoice_snapshot_invalid",
            "The invoice snapshot must be valid JSON",
        );
    }
    const invoiceId = invoiceIdFromSnapshot(snapshot);
    if (!invoiceId) {
        return pdfError(
            400,
            "invoice_snapshot_invalid",
            "The invoice snapshot must identify an invoice",
        );
    }

    const fingerprint = await computeInvoicePdfFingerprint(snapshot);
    const key = `v1/${appId}/${logId}/invoices/${invoiceId}`;
    const bucket = env.INVOICE_PDFS;

    const startedAt = Date.now();
    let existing: R2Object | null = null;
    try {
        existing = await bucket.head(key);
    } catch {
        logInvoicePdf("cache_read_failed", logId, invoiceId);
    }
    const hasMatchingObject = cachedObjectMatches(existing, fingerprint);
    if (hasMatchingObject && forceRegenerate) {
        // Keep `existing` for the conditional write below, but render fresh
        // bytes instead of serving the stored document.
        logInvoicePdf("cache_bypassed", logId, invoiceId);
    }
    if (hasMatchingObject && !forceRegenerate) {
        let cached: R2ObjectBody | null = null;
        try {
            cached = await bucket.get(key);
        } catch {
            cached = null;
        }
        if (cached && cachedObjectMatches(cached, fingerprint)) {
            const storedHeaders = new Headers();
            cached.writeHttpMetadata(storedHeaders);
            logInvoicePdf("cache_hit", logId, invoiceId, Date.now() - startedAt);
            return pdfResponse(cached.body, {
                contentType:
                    storedHeaders.get("Content-Type") ?? "application/pdf",
                contentDisposition: dispositionFor(cached, invoiceId),
                cache: "hit",
                isdocAttached: cached.customMetadata?.isdocAttached,
                fingerprint,
            });
        }
    }

    let rendererResponse: Response;
    try {
        rendererResponse = await fetch(`${env.INVOICE_RENDERER_ORIGIN.replace(/\/$/, "")}${RENDER_PATH}`, {
            method: "POST",
            headers: {
                "Content-Type": "application/json",
                Accept: "application/pdf, application/problem+json",
                Authorization: `Bearer ${env.INVOICE_RENDERER_TOKEN}`,
            },
            body,
        });
    } catch {
        logInvoicePdf("renderer_unreachable", logId, invoiceId);
        return pdfError(
            502,
            "invoice_renderer_unreachable",
            "The invoice renderer could not be reached",
        );
    }
    if (rendererResponse.status === 401) {
        // The public request is authenticated by Access; a 401 here means the
        // renderer rejected the server credential, so do not surface it as an
        // expired browser session.
        logInvoicePdf("renderer_credential_rejected", logId, invoiceId);
        return pdfError(
            502,
            "invoice_renderer_credential_rejected",
            "The invoice renderer rejected the server credential",
        );
    }
    if (!rendererResponse.ok) {
        logInvoicePdf("renderer_failed", logId, invoiceId);
        return passThroughRendererError(rendererResponse);
    }

    let bytes: Uint8Array;
    try {
        bytes = new Uint8Array(await rendererResponse.arrayBuffer());
    } catch {
        logInvoicePdf("renderer_interrupted", logId, invoiceId);
        return pdfError(
            502,
            "invoice_renderer_invalid_response",
            "The invoice renderer returned an unreadable response",
        );
    }
    const contentType = normalizedContentType(
        rendererResponse.headers.get("Content-Type"),
    );
    if (
        contentType !== "application/pdf" ||
        bytes.byteLength === 0 ||
        !startsWithPdfMagic(bytes)
    ) {
        // Error pages, empty responses and interrupted output are never cached
        // or shown as invoices.
        logInvoicePdf("renderer_invalid_response", logId, invoiceId);
        return pdfError(
            502,
            "invoice_renderer_invalid_response",
            "The invoice renderer did not return a valid PDF",
        );
    }

    const disposition =
        rendererResponse.headers.get("Content-Disposition") ??
        inlineDisposition(fallbackFileName(invoiceId));
    const fileName =
        filenameFromDisposition(disposition) ?? fallbackFileName(invoiceId);

    const attachmentHeader = rendererResponse.headers.get("X-Isdoc-Attached");
    const isdocAttached = attachmentHeader === "true" || attachmentHeader === "false" ? attachmentHeader : undefined;
    if (isRecord(snapshot) && snapshot.requireIsdoc === true && isdocAttached !== "true") {
        return pdfError(502, "invoice_isdoc_missing", "The invoice renderer did not attach the required electronic invoice");
    }
    let stored = false;
    let writeFailed = false;
    try {
        const result = await bucket.put(key, bytes, {
            httpMetadata: {
                contentType: "application/pdf",
                contentDisposition: disposition,
            },
            customMetadata: {
                kind: "pdf",
                invoiceId,
                fingerprint,
                rendererRevision: String(INVOICE_PDF_RENDERER_REVISION),
                fileName,
                generatedAt: new Date().toISOString(),
                ...(isdocAttached ? { isdocAttached } : {}),
            },
            // The precondition is captured before rendering: a concurrent
            // replacement, or a deletion marker written while rendering, wins
            // and this result is simply returned without being cached.
            onlyIf: existing
                ? { etagMatches: existing.httpEtag }
                : { etagDoesNotMatch: "*" },
        });
        stored = result !== null;
    } catch {
        writeFailed = true;
    }
    logInvoicePdf(
        writeFailed
            ? "cache_store_failed"
            : stored
              ? "cache_stored"
              : "cache_store_skipped",
        logId,
        invoiceId,
        Date.now() - startedAt,
    );

    return pdfResponse(bytes.buffer as ArrayBuffer, {
        status: 200,
        contentType: "application/pdf",
        contentDisposition: disposition,
        cache: "miss",
        isdocAttached,
        fingerprint,
    });
}

async function deleteInvoicePdf(
    bucket: R2Bucket,
    key: string,
    logId: string,
    invoiceId: string,
): Promise<Response> {
    // The marker body is irrelevant, but a unique marker id distinguishes a
    // deliberate deletion from a PDF in diagnostics and guarantees the object
    // etag changes so pre-deletion renders cannot restore their bytes.
    const markerId = crypto.randomUUID();
    try {
        await bucket.put(key, JSON.stringify({ deleted: true, markerId }), {
            httpMetadata: { contentType: "application/json" },
            customMetadata: {
                kind: "deleted",
                markerId,
                deletedAt: new Date().toISOString(),
            },
        });
    } catch {
        logInvoicePdf("delete_failed", logId, invoiceId);
        return pdfError(
            503,
            "invoice_pdf_delete_failed",
            "The saved invoice PDF could not be removed",
        );
    }
    logInvoicePdf("delete_marker", logId, invoiceId);
    return secureResponse(null, { status: 204 });
}

function cachedObjectMatches(
    object: R2Object | null,
    fingerprint: string,
): boolean {
    if (!object || object.size === 0) return false;
    const metadata = object.customMetadata;
    if (!metadata || metadata.kind === "deleted") return false;
    return (
        metadata.fingerprint === fingerprint &&
        metadata.rendererRevision === String(INVOICE_PDF_RENDERER_REVISION)
    );
}

function invoiceIdFromSnapshot(snapshot: unknown): string | null {
    if (!snapshot || typeof snapshot !== "object") return null;
    const invoice = (snapshot as { invoice?: unknown }).invoice;
    if (!invoice || typeof invoice !== "object") return null;
    const id = (invoice as { id?: unknown }).id;
    if (typeof id !== "string" || !new RegExp(`^${INVOICE_ID}$`).test(id)) {
        return null;
    }
    return id;
}

function startsWithPdfMagic(bytes: Uint8Array): boolean {
    if (bytes.byteLength < PDF_MAGIC.length) return false;
    for (let index = 0; index < PDF_MAGIC.length; index += 1) {
        if (bytes[index] !== PDF_MAGIC.charCodeAt(index)) return false;
    }
    return true;
}

function normalizedContentType(value: string | null): string {
    return value?.split(";", 1)[0]?.trim().toLowerCase() ?? "";
}

function isJsonContentType(value: string | null): boolean {
    return normalizedContentType(value) === "application/json";
}

function fallbackFileName(invoiceId: string): string {
    return `faktura-${invoiceId}.pdf`;
}

function inlineDisposition(fileName: string): string {
    const fallback =
        fileName.replace(/[^a-zA-Z0-9._ -]/g, "_").replace(/["\\]/g, "_") ||
        "invoice.pdf";
    return `inline; filename="${fallback}"; filename*=UTF-8''${encodeURIComponent(fileName)}`;
}

function dispositionFor(object: R2Object, invoiceId: string): string {
    const headers = new Headers();
    object.writeHttpMetadata(headers);
    return (
        headers.get("Content-Disposition") ??
        inlineDisposition(object.customMetadata?.fileName ?? fallbackFileName(invoiceId))
    );
}

function filenameFromDisposition(value: string): string | null {
    const encoded = /filename\*\s*=\s*UTF-8''([^;]+)/i.exec(value);
    if (encoded?.[1]) {
        try {
            return decodeURIComponent(encoded[1].trim().replace(/^"|"$/g, ""));
        } catch {
            // Fall through to the plain filename parameter.
        }
    }
    const quoted = /filename\s*=\s*"([^"]+)"/i.exec(value);
    if (quoted?.[1]) return quoted[1];
    const bare = /filename\s*=\s*([^;]+)/i.exec(value);
    return bare?.[1]?.trim() || null;
}

function passThroughRendererError(response: Response): Response {
    const headers = new Headers();
    const contentType = response.headers.get("Content-Type");
    if (contentType) headers.set("Content-Type", contentType);
    headers.set("Cache-Control", "private, no-store");
    headers.set("X-Content-Type-Options", "nosniff");
    return new Response(response.body, { status: response.status, headers });
}

function isRecord(value: unknown): value is Record<string, unknown> {
    return value !== null && typeof value === "object" && !Array.isArray(value);
}

function pdfResponse(
    body: BodyInit | null,
    options: {
        status?: number;
        contentType: string;
        contentDisposition: string;
        cache: "hit" | "miss";
        isdocAttached?: string;
        fingerprint: string;
    },
): Response {
    const headers = new Headers({
        "Content-Type": options.contentType,
        "Content-Disposition": options.contentDisposition,
        "Cache-Control": "private, no-store",
        "X-Content-Type-Options": "nosniff",
        "X-Invoice-Pdf-Cache": options.cache,
        "X-Invoice-Pdf-Fingerprint": options.fingerprint,
        "X-Invoice-Renderer-Revision": String(INVOICE_PDF_RENDERER_REVISION),
    });
    if (options.isdocAttached === "true" || options.isdocAttached === "false") headers.set("X-Isdoc-Attached", options.isdocAttached);
    return new Response(body, { status: options.status ?? 200, headers });
}

function tooLargeError(): Response {
    return pdfError(
        413,
        "invoice_snapshot_too_large",
        "The invoice snapshot is too large to render",
    );
}

function pdfError(status: number, code: string, error: string): Response {
    return pdfResponse(JSON.stringify({ error, code }), {
        status,
        contentType: "application/json; charset=utf-8",
        contentDisposition: "inline",
        cache: "miss",
        fingerprint: "",
    });
}

function secureResponse(body: BodyInit | null, init: ResponseInit = {}): Response {
    const headers = new Headers(init.headers);
    headers.set("Cache-Control", "private, no-store");
    headers.set("X-Content-Type-Options", "nosniff");
    return new Response(body, { ...init, headers });
}

/** Structured diagnostics without invoice contents. */
function logInvoicePdf(
    outcome: string,
    logId: string,
    invoiceId: string,
    durationMs?: number,
): void {
    console.log(
        JSON.stringify({
            event: "invoice_pdf_cache",
            outcome,
            logId,
            invoiceId,
            ...(durationMs === undefined ? {} : { durationMs }),
        }),
    );
}
